with flattened as (select id, plan, explode_outer(tier_limits) as tier_value from price_tiers), filtered as (select *, substring(plan, 1, 2) as plan_prefix from flattened where tier_value < 31), enriched as (select plan, tier_value, plan_prefix, count(tier_value) over (partition by plan) as plan_count_tier_value, cume_dist() over (partition by plan order by tier_value) as tier_value_cume_dist, rank() over (partition by plan order by tier_value desc nulls last) as tier_value_rank, cume_dist() over (order by tier_value desc) as tier_value_cume_dist_2 from filtered where plan = 'enterprise'), with_windows as (select *, round(plan_count_tier_value / sum(plan_count_tier_value) over (partition by plan), 4) as plan_count_tier_value_share, stddev_samp(tier_value) over (partition by plan) as plan_stddev_samp_tier_value from enriched) select tier_value, plan_count_tier_value, tier_value_cume_dist, tier_value_rank, plan_stddev_samp_tier_value from with_windows order by plan_count_tier_value nulls first;
